local cs_coroutine = require 'XLua.cs_coroutine'
local Yielders = CS.Engine.Lib.Yielders
--- from: Assets/BundleResources/Prefabs/ChapterNew/ChapterNormal.prefab
---@class ChapterMessage
---@field Env                           	ChapterMessage                          
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field ScrollView                    	UnityEngine.RectTransform               
---@field ImgHeadSculpture              	UnityEngine.RectTransform               
---@field ImgHeadSculptureBg            	UnityEngine.RectTransform               
---@field TextTitle                     	UnityEngine.RectTransform               
---@field Message                       	UnityEngine.Animation                   
local ChapterMessage = Class('ChapterMessage')
local CellPath = "Game.Chapter.ChapterMessageCell"

function ChapterMessage:__init()
    self.co = nil
    self.messageWaiter = nil
end

function ChapterMessage:__delete()
    self:StopMessageCo()
    self.messageData = nil
    self.aniData = nil
end

function ChapterMessage:Awake()
end

function ChapterMessage:Start()
end

function ChapterMessage:InitData()
    if isNull(self.messageData) then
        self.messageData = {}
    end

    if isNull(self.aniData) then
        self.aniData = {}
    end
end

function ChapterMessage:StartMessage(messageId)
    self:InitData()
    local waiter = { wait = true }
    ---如果大于0  就不用去设置聊天室的名称和头像

    -- 停止旧消息时同时释放旧调用的等待状态，避免旧 StartMessage 永久卡住。
    self:StopMessageCo()
    self.messageWaiter = waiter

    self.co = cs_coroutine.start(function()
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting6054, "NewChapterMessageVo", messageId)
        if not (table.count(self.messageData) > 0) then
            self:SetTitleInfo(vo)
            self:PlayAni("ChapterNormal_ChapterNewUI_Message_Entry")
        end
        table.insert(self.messageData,vo)
        self:RefreshGridView()
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(vo.waitTime))
        waiter.wait = false
        if self.messageWaiter == waiter then
            self.messageWaiter = nil
            self.co = nil
        end
    end)
    while waiter.wait do
        coroutine.yield()
    end
end

function ChapterMessage:StopMessageCo()
    if self.messageWaiter ~= nil then
        self.messageWaiter.wait = false
        self.messageWaiter = nil
    end

    if self.co ~= nil then
        cs_coroutine.stop(self.co)
        self.co = nil
    end
end

function ChapterMessage:PlayAni(aniName)
    self.Message:Play(aniName)
end

function ChapterMessage:RefreshGridView()
    if not self.ScrollView.IsListViewInit then
        self.ScrollView:InitListView(#self.messageData, Bind(self, self.OnRefreshCellIndex))
        self.ScrollView:MovePanelToItemIndex(#self.messageData - 1,0)
    else
        GameUtils.ReloadData(self.ScrollView, #self.messageData)
        self.ScrollView:MovePanelToItemIndex(#self.messageData - 1,0)
    end
end

function ChapterMessage:OnRefreshCellIndex(listView,index)
    if index < 0 or index >= #self.messageData then
        return
    end
    local data = self.messageData[index + 1]
    local cellName =data.isMe and "OthersCell" or "MyselfCell"
    local aniName = data.isMe and "OverseaChatDialog_OthersCellGo" or "OverseaChatDialog_MyselfCellGo"
    local cell = listView:NewListViewItem(cellName)
    local cellEnv = CfUtils.GetLuaScr(cell, CellPath)
    if cellEnv then
        cellEnv:RefreshUI(data)
        if data.isShowHint and (index + 1) == #self.messageData then
            cellEnv:SetHintStatus(true)
        else
            cellEnv:SetHintStatus(false)
        end
        if not self.aniData[index + 1] then
            self.aniData[index + 1] = true
            cellEnv:PlayAni(aniName)
        end
    end
    return cell
end

function ChapterMessage:SetTitleInfo(vo)
    CfUtils.FillText(self.TextTitle,vo.head1Text)
    CfUtils.FillImage(self.ImgHeadSculpture,vo.head1)
end

function ChapterMessage:CleanMessageData()
    self:StopMessageCo()
    self.messageData = {}
    self.aniData = {}
end

function ChapterMessage:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return ChapterMessage
